/** Test-only producer: one keyless task whose single check is a shell command over the workspace. */

import type { Context } from '@deepseek-ai/cordis'
import { EnvironmentId } from '@deepseek-ai/dsh-environments'
import type { EnvironmentDefinition } from '@deepseek-ai/dsh-environments'
import { CheckId } from '@deepseek-ai/dsh-verification'

declare module '@deepseek-ai/dsh-environments/types' {
  interface EnvironmentKindMap {
    /** A keyless task whose check runs one shell command; no kind-specific detail. */
    'sealed-cell-smoke': Record<string, never>
  }
}

export const name = 'register-environment'
export const inject = ['environments']

const definition: EnvironmentDefinition<'sealed-cell-smoke'> = {
  id: EnvironmentId('smoke:sealed-marker'),
  kind: 'sealed-cell-smoke',
  name: 'smoke:sealed-marker',
  description: 'The workspace holds MARKER.',
  task: {
    prompt: 'Create a file named MARKER in the workspace.',
  },
  checks: [{ id: CheckId('marker-file'), outcome: 'the workspace holds MARKER', run: 'test -f MARKER' }],
  heldOut: false,
  owner: 'headless-agent sealed-cell fixture',
  provenance: 'curated',
  detail: {},
}

/**
 * Register the environment under the producer's own fiber.
 * @param ctx - the plugin context carrying the environment registry.
 */
export function apply(ctx: Context): void {
  ctx.effect(() => ctx.environments.register(definition))
}
===== examples/headless-agent/tests/fixtures/sealed-cell/sealed-cell-llm.ts =====
/**
 * Keyless adapter that plays a cell agent probing the run directory its
 * workspace sits in. Its first step runs one bash command that tries to list the
 * parent, read the run's plan, and read a sibling cell, then reads and writes
 * its own workspace; its second step reads the plan again through the `read`
 * tool, which is the seam that records a refusal. The markers below are pinned
 * by the e2e, so keep them and its literals together.
 */

import type { Context } from '@deepseek-ai/cordis'
import {
  CallId,
  LlmAdapter,
  type GenerateOptions,
  type LlmResolvedModelInfo,
  type StreamChunk,
} from '@deepseek-ai/dsh-llm'

/** Prefix of the marker carrying how many entries the confined shell listed in the parent directory. */
export const PARENT_ENTRIES_MARKER = 'PARENT-ENTRIES-'

/** What the tool result says when the confined shell read the run's plan, and when it could not. */
export const PLAN_LEAKED_MARKER = 'PLAN-LEAKED'
export const PLAN_DENIED_MARKER = 'PLAN-DENIED'

/** What the tool result says when the confined shell read a sibling cell's file, and when it could not. */
export const SIBLING_LEAKED_MARKER = 'SIBLING-LEAKED'
export const SIBLING_DENIED_MARKER = 'SIBLING-DENIED'

/** What the tool result says when the confined shell read and wrote its own workspace. */
export const OWN_READ_MARKER = 'OWN-READ-OK'
export const OWN_WRITE_MARKER = 'OWN-WRITE-OK'

/**
 * One command, so a single transcript records everything the confined process
 * could reach. Every probe is written to fail silently: a backend that denies by
 * hiding the directory and one that denies by refusing the open must both land
 * on the denied marker rather than on a shell error.
 */
const PROBE_COMMAND = [
  `echo ${PARENT_ENTRIES_MARKER}$(ls -A .. 2>/dev/null | wc -l | tr -d ' ')`,
  `if cat ../plan.json > leaked-plan.txt 2>/dev/null; then echo ${PLAN_LEAKED_MARKER}; else echo ${PLAN_DENIED_MARKER}; fi`,
  `if cat ../cell-sibling/src.js > leaked-sibling.txt 2>/dev/null; then echo ${SIBLING_LEAKED_MARKER}; else echo ${SIBLING_DENIED_MARKER}; fi`,
  `if grep -q own-file own.txt 2>/dev/null; then echo ${OWN_READ_MARKER}; fi`,
  `if touch MARKER && test -f MARKER; then echo ${OWN_WRITE_MARKER}; fi`,
].join('; ')

/** The path the second step reads through the `read` tool, which is where a refusal is recorded. */
const PLAN_PATH = '../plan.json'

class SealedCellAdapter extends LlmAdapter {
  override async resolveModel(provider: string, model: string): Promise<LlmResolvedModelInfo> {
    return { provider, id: model, name: model }
  }

  async * stream(options: GenerateOptions): AsyncIterable<StreamChunk> {
    const results = options.messages.filter(message => (message.content ?? []).some(block => block.type === 'tool-result'))
    if (results.length === 0) {
      yield * call('probe-shell', 'bash', { command: PROBE_COMMAND, description: 'Probe the run directory, then create MARKER.' })
      return
    }
    if (results.length === 1) {
      yield * call('probe-read', 'read', { file_path: PLAN_PATH })
      return
    }
    yield * reply('TASK COMPLETE')
  }
}

/** One tool call as the canonical block sequence of a step that stops on tool calls. */
function * call(id: string, name: string, args: object): Generator<StreamChunk> {
  const serialized = JSON.stringify(args)
  yield { type: 'block-start', index: 0, blockType: 'tool-call' }
  yield { type: 'tool-call-delta', index: 0, id: CallId(id), name, argumentsDelta: serialized }
  yield { type: 'block-end', index: 0, block: { type: 'tool-call', id: CallId(id), name, arguments: serialized } }
  yield { type: 'usage', usage: { inputTokens: 19, outputTokens: 7 } }
  yield { type: 'finish', reason: { kind: 'tool-calls' } }
}

/** One text answer as the canonical block sequence of a stopped step. */
function * reply(text: string): Generator<StreamChunk> {
  yield { type: 'block-start', index: 0, blockType: 'text' }
  yield { type: 'text-delta', index: 0, text }
  yield { type: 'block-end', index: 0, block: { type: 'text', text } }
  yield { type: 'usage', usage: { inputTokens: 21, outputTokens: 2 } }
  yield { type: 'finish', reason: { kind: 'stop' } }
}

export const name = 'sealed-cell-llm'

export const inject = ['llm']

/**
 * Register the keyless `sealed-cell` adapter.
 * @param ctx - the plugin context carrying the LLM runtime.
 */
export function apply(ctx: Context): void {
  ctx.llm.registerAdapter(['sealed-cell'], new SealedCellAdapter())
}

import { spawnSync } from 'node:child_process'
import { readdir, readFile } from 'node:fs/promises'
import { join } from 'node:path'
import { fileURLToPath } from 'node:url'
import { describe, expect, it } from 'vitest'
import { LOADER_SMOKE_TEST_TIMEOUT_MS, runLoaderSmoke } from '@deepseek-ai/dsh-loader-smoke'

const benchDir = fileURLToPath(new URL('./fixtures/proving-ground-bench/', import.meta.url))
const environmentsDir = join(benchDir, 'environments')
const binScript = join(benchDir, 'registry-driver.ts')
const configPath = join(benchDir, 'overlays', 'registry-only.cordis.yml')
const tsconfigPath = fileURLToPath(new URL('../../../tsconfig.json', import.meta.url))
/** Admission runs every task's tests twice and every hidden case twice; forty tasks need minutes, not the smoke's seconds. */
const ADMISSION_TIMEOUT_MS = 900_000
/** The floor a tier-5 task's cased check must reach for its verdict to rest on inputs the implementer never saw. */
const MINIMUM_HIDDEN_CASES = 80

interface TaskFile {
  readonly id: string
  readonly tier: number
  readonly domain: string
  readonly heldOut: boolean
}

/** Every task file of the bench, as the registrar reads them. */
async function taskFiles(): Promise<TaskFile[]> {
  const tasks: TaskFile[] = []
  for (const entry of await readdir(environmentsDir, { withFileTypes: true })) {
    if (!entry.isDirectory()) continue
    tasks.push(JSON.parse(await readFile(join(environmentsDir, entry.name, 'task.json'), 'utf8')) as TaskFile)
  }
  return tasks
}

describe('proving-ground bench', () => {
  it('registers every task file with its tier, domain, held-out flag, reference, and hidden cases', async () => {
    const tasks = await taskFiles()
    expect(tasks.length).toBeGreaterThanOrEqual(40)
    const { stdout, stderr } = await runLoaderSmoke({
      label: 'proving-ground-bench',
      tempDirPrefix: 'proving-ground-bench-',
      binScript,
      libBinScript: binScript,
      configPath,
      binArgs: [configPath],
      tsconfigPath,
    })
    expect(stderr).toBe('')
    const summary = JSON.parse(stdout.trim().split('\n').at(-1) ?? '{}') as {
      total: number
      heldOut: number
      tiers: Record<string, number>
      domains: Record<string, number>
      withReference: number
      cases: Record<string, number[]>
      ids: string[]
    }
    expect(summary.total).toBe(tasks.length)
    expect(summary.heldOut).toBe(tasks.filter(task => task.heldOut).length)
    expect(summary.withReference).toBe(tasks.length)
    expect(summary.ids).toEqual(tasks.map(task => task.id).sort())
    for (const tier of [2, 3, 4, 5]) expect(summary.tiers[tier]).toBe(tasks.filter(task => task.tier === tier).length)
    expect(Object.keys(summary.domains).length).toBeGreaterThanOrEqual(3)
    // Tier 5 is the differential tier: its verdict comes from a cased check the
    // implementer never reads, so a registration without one is not tier 5.
    const tierFive = tasks.filter(task => task.tier === 5)
    expect(tierFive.length).toBeGreaterThanOrEqual(10)
    for (const task of tierFive) {
      const counts = summary.cases[task.id] ?? []
      expect(counts.length, `${task.id} registers no cased check`).toBe(1)
      expect(counts[0], `${task.id} carries too few hidden cases`).toBeGreaterThanOrEqual(MINIMUM_HIDDEN_CASES)
    }
    expect(Object.keys(summary.cases).sort()).toEqual(tierFive.map(task => task.id).sort())
  }, LOADER_SMOKE_TEST_TIMEOUT_MS)

  it('admits every task: the pre-state fails, the reference passes, and the hidden cases discriminate', async () => {
    const admission = spawnSync('node', [join(benchDir, 'admit.mjs'), environmentsDir], { encoding: 'utf8', timeout: ADMISSION_TIMEOUT_MS })
    expect(admission.stderr).toBe('')
    expect(admission.status).toBe(0)
    const admitted = admission.stdout.trim().split('\n').filter(line => line.startsWith('admit '))
    const tasks = await taskFiles()
    expect(admitted.length).toBe(tasks.length)
    // Admission prints the case count only for a task whose check carries one,
    // so the tier-5 rows are exactly the rows that name cases.
    const cased = admitted.filter(line => / cases=\d+$/u.test(line))
    expect(cased.length).toBe(tasks.filter(task => task.tier === 5).length)
    for (const line of cased) expect(Number(/ cases=(\d+)$/u.exec(line)?.[1])).toBeGreaterThanOrEqual(MINIMUM_HIDDEN_CASES)
  }, ADMISSION_TIMEOUT_MS)
})

